-- Generated by scripts/build_compiled.py from src/fraudrules/rules/synthetic-identity/si-002-phone-shared-across-ssns.yaml. Do not edit.
-- SI-002 Phone number shared by several SSNs within a short period
SELECT 'SI-002' AS rule_id, 'applications' AS anchor_table, a.id AS anchor_id
FROM applications AS a
JOIN applications AS b ON b.phone_token = a.phone_token AND b.ts <= a.ts AND b.ts > a.ts - 7776000
WHERE 1 = 1 AND 1 = 1
GROUP BY a.id
HAVING COUNT(DISTINCT b.ssn_token) >= 3;
